        var count = 0;
        for (var i = 0; i < selected.length; i++) {
            var layer = selected[i];
            var props = ["Position", "Scale", "Opacity", "Rotation"];
            for (var p = 0; p < props.length; p++) {
                var prop = layer.property(props[p]);
                if (prop && prop.numKeys > 1 && prop.canSetExpression) {
                    prop.expression = 'loopOut("pingpong");';
                    count++;
                }
            }
        }
        return "SUCCESS: Applied loopOut('pingpong') to " + count + " properties.";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
