(function() {
    app.beginUndoGroup("Apply Venetian Blinds (Transition)");
    try {
        var comp = app.project.activeItem;
        if (!(comp instanceof CompItem)) return "ERROR: Please open a composition.";
        var selected = comp.selectedLayers;
        if (selected.length === 0) return "ERROR: Select at least one layer.";
        for (var i = 0; i < selected.length; i++) {
            var effects = selected[i].property("ADBE Effect Parade");
            var eff = effects.addProperty("ADBE Venetian Blinds");
            var t0 = selected[i].inPoint;
            if (eff.property("Transition Completion")) {
                eff.property("Transition Completion").setValueAtTime(t0, 0);
                eff.property("Transition Completion").setValueAtTime(t0 + 1.0, 100);
            }
            if (eff.property("Width")) eff.property("Width").setValue(30);
            if (eff.property("Feather")) eff.property("Feather").setValue(10);
        }
        return "SUCCESS: Applied Venetian Blinds to " + selected.length + " layer(s).";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
})();

