        var t0 = shapeLayer.inPoint;
        endProp.setValueAtTime(t0, 0);
        endProp.setValueAtTime(t0 + 2.0, 100);

        return "SUCCESS: Created animated circular stroke with Trim Paths.";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
