            sc.setValueAtTime(t0, [0, 0]);
            sc.setValueAtTime(t0 + (1.18 * 0.7), [110, 110]);
            sc.setValueAtTime(t1, [100, 100]);
        }
        return "SUCCESS: Entrance animation applied.";
