(function() {
    app.beginUndoGroup("Vector Path Morph (Circle to Star)");
    try {
        var comp = app.project.activeItem;
        if (!(comp instanceof CompItem)) return "ERROR: Please open a composition.";
        var shapeLayer = comp.layers.addShape();
        shapeLayer.name = "Morphing Shape (Circle to Star)";
        var contents = shapeLayer.property("ADBE Root Vectors Group");
        var group = contents.addProperty("ADBE Vector Group");
        var groupContents = group.property("ADBE Vectors Group");

        var pathGroup = groupContents.addProperty("ADBE Vector Shape - Group");
        var pathProp = pathGroup.property("ADBE Vector Shape");

        var fill = groupContents.addProperty("ADBE Vector Graphic - Fill");
        fill.property("ADBE Vector Fill Color").setValue([0.2, 0.65, 1.0]);

        var s1 = new Shape();
        s1.vertices = [[-150, -150], [150, -150], [150, 150], [-150, 150]];
        s1.closed = true;

        var s2 = new Shape();
        s2.vertices = [[0, -220], [80, -60], [220, -60], [100, 40]];
        s2.closed = true;

        var t0 = shapeLayer.inPoint;
        pathProp.setValueAtTime(t0, s1);
        pathProp.setValueAtTime(t0 + 1.5, s2);

        return "SUCCESS: Created shape morphing animation (Circle to Star).";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
})();

