            var pos = layer.property("Position");
            if (pos && pos.canSetExpression) {
                pos.expression = "wiggle(3, 35);";
            }
        }
        return "SUCCESS: Applied Glow and Wiggle to " + selected.length + " layer(s).";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
})();

